class Solution:
    def maximumStrength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        NEG = float("-inf")
        dp = [[NEG] * (n + 1) for _ in range(k + 1)]
        cur = [[NEG] * (n + 1) for _ in range(k + 1)]
        for i in range(n + 1):
            dp[0][i] = 0
        for j in range(1, k + 1):
            c = (k - j + 1) * (1 if j % 2 == 1 else -1)
            for i in range(1, n + 1):
                m = dp[j - 1][i - 1]
                if cur[j][i - 1] > m:
                    m = cur[j][i - 1]
                cur[j][i] = m + c * nums[i - 1]
                dp[j][i] = max(dp[j][i - 1], cur[j][i])
        return dp[k][n]

