class Solution {
public:
    long long maximumStrength(vector<int>& nums, int k) {
        int n = nums.size();
        const long long NEG = LLONG_MIN / 4;
        vector<vector<long long>> dp(k + 1, vector<long long>(n + 1, NEG));
        vector<vector<long long>> cur(k + 1, vector<long long>(n + 1, NEG));
        for (int i = 0; i <= n; i++) dp[0][i] = 0;
        for (int j = 1; j <= k; j++) {
            long long c = (long long)(k - j + 1) * (j % 2 ? 1 : -1);
            for (int i = 1; i <= n; i++) {
                long long m = dp[j - 1][i - 1];
                if (cur[j][i - 1] > m) m = cur[j][i - 1];
                cur[j][i] = m + c * (long long)nums[i - 1];
                dp[j][i] = max(dp[j][i - 1], cur[j][i]);
            }
        }
        return dp[k][n];
    }
};

