class Solution {
    public long maximumStrength(int[] nums, int k) {
        int n = nums.length;
        final long NEG = Long.MIN_VALUE / 4;
        long[][] dp = new long[k + 1][n + 1];
        long[][] cur = new long[k + 1][n + 1];
        for (long[] row : dp) java.util.Arrays.fill(row, NEG);
        for (long[] row : cur) java.util.Arrays.fill(row, NEG);
        for (int i = 0; i <= n; i++) dp[0][i] = 0;
        for (int j = 1; j <= k; j++) {
            long c = (long)(k - j + 1) * (j % 2 == 1 ? 1 : -1);
            for (int i = 1; i <= n; i++) {
                long m = Math.max(dp[j - 1][i - 1], cur[j][i - 1]);
                cur[j][i] = m + c * (long) nums[i - 1];
                dp[j][i] = Math.max(dp[j][i - 1], cur[j][i]);
            }
        }
        return dp[k][n];
    }
}

