var maximumStrength = function(nums, k) {
    const n = nums.length, NEG = -1e18;
    const dp = Array.from({length: k + 1}, () => new Array(n + 1).fill(NEG));
    const cur = Array.from({length: k + 1}, () => new Array(n + 1).fill(NEG));
    for (let i = 0; i <= n; i++) dp[0][i] = 0;
    for (let j = 1; j <= k; j++) {
        const c = (k - j + 1) * (j % 2 === 1 ? 1 : -1);
        for (let i = 1; i <= n; i++) {
            const m = Math.max(dp[j - 1][i - 1], cur[j][i - 1]);
            cur[j][i] = m + c * nums[i - 1];
            dp[j][i] = Math.max(dp[j][i - 1], cur[j][i]);
        }
    }
    return dp[k][n];
};
